<template>
  <input
    type="range"
    :value="modelValue"
    @input="this.$emit('update:modelValue', parseFloat($event.target.value))"
  />
</template>

<script>
export default {
  name: "Slider",
  props: ["modelValue"],
  emits: ["update:modelValue"],
};
</script>

<style scoped lang="scss">
input {
  -webkit-appearance: none;
  height: 10px;
  background: darken($foreground, 2%);
  border-radius: $radius-sm;
}

input:hover {
  opacity: 1;
}

input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 15px;
  height: 20px;
  background: $blue;
  cursor: pointer;
  border-radius: $radius-sm;
  transition: background 0.4s;

  &:hover {
    background: darken($blue, 5%);
  }
}
</style>
